"\"\"\"Auto-tests de l'expérience distillation jacobienne.\n\n1. Gradient du backward de distillation (KL) contre différences finies sur un mini-modèle.\n2. Champ parent MLP : intégrabilité (curl) vérifiée numériquement.\n3. gen_fit / genfree_fit : gradients contre différences finies.\n4. Smoke test : parent gauss, 30 pas de distillation, la perte doit baisser.\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom distill_model import DistillTransformer\nfrom parent import make_field\nimport e1_field\n\nok = True\n\n\ndef check(name, cond, detail=\"\"):\n    global ok\n    print(f\"{'PASS' if cond else 'FAIL'} — {name} {detail}\")\n    ok = ok and cond\n\n\n# ---------------------------------------------------------------- 1. gradient distill\nrng = np.random.default_rng(0)\nV, d, d_ff, L, H, T, B = 11, 8, 16, 2, 2, 6, 2\nmodel = DistillTransformer(V, d, d_ff, L, H, T, rng, dtype=np.float64)\nW1s = [rng.standard_normal((d_ff, d)) * 0.1 for _ in range(L)]\nX = rng.integers(0, V, (B, T))\nPT = np.abs(rng.standard_normal((B, T, V)))\nPT = (PT / PT.sum(-1, keepdims=True)).astype(np.float64)\n\nloss, cache = model.forward_distill(X, W1s, PT)\ngrads, Gs = model.backward(cache, W1s)\n\n# différences finies sur quelques paramètres\nkeys = [\"E\", \"P\", \"gf\", \"Wq_0\", \"b1f_1\", \"W2_1\", \"g2_0\"]\neps = 1e-6\nmax_rel = 0.0\nfor k in keys:\n    flat = model.params[k].reshape(-1)\n    for j in rng.choice(flat.size, size=min(3, flat.size), replace=False):\n        old = flat[j]\n        flat[j] = old + eps\n        lp, _ = model.forward_distill(X, W1s, PT)\n        flat[j] = old - eps\n        lm, _ = model.forward_distill(X, W1s, PT)\n        flat[j] = old\n        fd = (lp - lm) / (2 * eps)\n        an = grads[k].reshape(-1)[j]\n        rel = abs(an - fd) / max(1e-8, abs(fd))\n        max_rel = max(max_rel, rel)\ncheck(\"grad distill vs différences finies\", max_rel < 5e-3, f\"(rel max {max_rel:.1e})\")\n\n# ∂L/∂W1\nGf = np.zeros((L, d_ff, d))\nmax_rel = 0.0\nfor l in range(L):\n    for (i, j) in [(0, 0), (3, 2), (d_ff - 1, d - 1)]:\n        Wp = W1s[l].copy(); Wp[i, j] += eps\n        Wm = W1s[l].copy(); Wm[i, j] -= eps\n        lp, _ = model.forward_distill(X, [Wp if m == l else W1s[m] for m in range(L)], PT)\n        lm, _ = model.forward_distill(X, [Wm if m == l else W1s[m] for m in range(L)], PT)\n        fd = (lp - lm) / (2 * eps)\n        an = Gs[l][i, j]\n        max_rel = max(max_rel, abs(an - fd) / max(1e-8, abs(fd)))\ncheck(\"grad ∂L/∂W1 vs différences finies\", max_rel < 5e-3, f\"(rel max {max_rel:.1e})\")\n\n# ---------------------------------------------------------------- 2. intégrabilité parent MLP\nfield = make_field(\"mlp\", 3)\nrng2 = np.random.default_rng(5)\nd_par = field[\"M\"].shape[1]\neps = 1e-6\nworst = 0.0\nfor _ in range(3):\n    uu = rng2.standard_normal(d_par) * 0.5\n    for (js, ks) in [(0, 1), (5, 9), (13, 20)]:\n        ejs = np.zeros(d_par); ejs[js] = 1\n        eks = np.zeros(d_par); eks[ks] = 1\n        a1 = field[\"Wstar\"](uu + eps * eks + eps * ejs)\n        a2 = field[\"Wstar\"](uu + eps * eks)\n        a3 = field[\"Wstar\"](uu + eps * ejs)\n        a4 = field[\"Wstar\"](uu)\n        lhs = (a2 - a4) / eps     # ∂_ks W(uu) → colonne js : ∂_ks W[:, js]\n        rhs = (a3 - a4) / eps     # ∂_js W(uu) → colonne ks : ∂_js W[:, ks]\n        num = float(np.abs(lhs[:, js] - rhs[:, ks]).max())\n        den = float(np.abs(lhs[:, js]).max() + np.abs(rhs[:, ks]).max() + 1e-30)\n        worst = max(worst, num / den)\ncheck(\"parent MLP : intégrabilité (∂_ks W[:,js] = ∂_js W[:,ks])\", worst < 1e-4, f\"(rel {worst:.1e})\")\n\n# ---------------------------------------------------------------- 3. gradients des fitters E1\nd_, dff, m_, K = 8, 12, 3, 4\nrng3 = np.random.default_rng(7)\nobs_u = rng3.standard_normal((m_, d_))\nobs_W = rng3.standard_normal((m_, dff, d_)) * 0.3 + 0.1 * np.eye(dff, d_)\np0 = np.concatenate([e1_field._gauss_init(K, d_, dff, obs_u, rng3)])\ni0 = dff * d_\nM0 = rng3.standard_normal((dff, d_)) * 0.1\np0 = np.concatenate([M0.reshape(-1), p0])\nI = np.eye(d_)\n\n\ndef gen_lg(p):\n    return e1_field._gen_loss_grad(p, obs_u, obs_W, K, d_, dff)\n\n\nL0, g0 = gen_lg(p0)\nmax_rel = 0.0\nfor j in rng3.choice(p0.size, size=6, replace=False):\n    pp = p0.copy(); pp[j] += 1e-5\n    Lp, _ = gen_lg(pp)\n    pm = p0.copy(); pm[j] -= 1e-5\n    Lm, _ = gen_lg(pm)\n    fd = (Lp - Lm) / 2e-5\n    max_rel = max(max_rel, abs(g0[j] - fd) / max(1e-8, abs(fd)))\ncheck(\"gen_fit gradient vs différences finies\", max_rel < 5e-4, f\"(rel max {max_rel:.1e})\")\n\n# genfree\np0f = np.concatenate([M0.reshape(-1), e1_field._gauss_init(5, d_, dff, obs_u, rng3, extra_b=True)])\nLf, gf = None, None\niF = dff * d_\n\n\ndef free_lg(p):\n    Kf = 5\n    q = p[iF:]\n    C = q[:Kf * d_].reshape(Kf, d_); q2 = q[Kf * d_:]\n    logR = q2[:Kf]; q2 = q2[Kf:]\n    A = q2[:Kf * dff].reshape(Kf, dff)\n    Bv = q2[Kf * dff:].reshape(Kf, d_)\n    M = p[:iF].reshape(dff, d_)\n    W = np.repeat(M[None], m_, axis=0)\n    phis = []\n    for k in range(Kf):\n        R = float(np.exp(logR[k]))\n        dvec = obs_u - C[k]\n        phi = np.exp(-np.sum(dvec ** 2, 1) / (2 * R * R))\n        phis.append((phi, dvec, R))\n        for i in range(m_):\n            W[i] += phi[i] * np.outer(A[k], Bv[k])\n    E = W - obs_W\n    L = 0.5 * float(np.sum(E ** 2))\n    gM = E.sum(0)\n    gC = np.zeros((Kf, d_)); gR = np.zeros(Kf)\n    gA = np.zeros((Kf, dff)); gB = np.zeros((Kf, d_))\n    for k in range(Kf):\n        phi, dvec, R = phis[k]\n        for i in range(m_):\n            gA[k] += phi[i] * (E[i] @ Bv[k])\n            gB[k] += phi[i] * (E[i].T @ A[k])\n            dphi = float(A[k] @ E[i] @ Bv[k])\n            gC[k] += dphi * (phi[i] * dvec[i] / R ** 2)\n            gR[k] += dphi * phi[i] * float(dvec[i] @ dvec[i]) / R ** 2\n    return L, np.concatenate([gM.reshape(-1), gC.reshape(-1), gR, gA.reshape(-1), gB.reshape(-1)])\n\n\nL0, g0 = free_lg(p0f)\nmax_rel = 0.0\nfor j in rng3.choice(p0f.size, size=6, replace=False):\n    pp = p0f.copy(); pp[j] += 1e-5\n    Lp, _ = free_lg(pp)\n    pm = p0f.copy(); pm[j] -= 1e-5\n    Lm, _ = free_lg(pm)\n    fd = (Lp - Lm) / 2e-5\n    max_rel = max(max_rel, abs(g0[j] - fd) / max(1e-8, abs(fd)))\ncheck(\"genfree_fit gradient vs différences finies\", max_rel < 5e-4, f\"(rel max {max_rel:.1e})\")\n\n# ---------------------------------------------------------------- 4. smoke test distillation\nimport parent as P\nfrom phase3_model import Transformer\nfrom phase3_methods import make_provider\nfrom phase3_corpus import get_task\n\npar = P.build_parent(\"gauss\", 0, steps=60)\nteacher = Transformer(par[\"V\"], P.D, P.D_FF, P.L, P.H, P.T, np.random.default_rng(1))\nteacher.params = par[\"parent_params\"]\nW1s_t = par[\"field\"][\"Ws\"]\ntrain, _ = get_task(\"a\", seed=0)\nrng4 = np.random.default_rng(42)\nstudent = DistillTransformer(train.V, P.D, P.D_FF, P.L, P.H, P.T, rng4)\nprov = make_provider(\"gen\", P.D, P.D_FF, P.L, rng4, K=6, r=2, e_dim=8, Hh=6)\nbrng = np.random.default_rng(50000)\nkls = []\nfor step in range(30):\n    X = train.sample_batch(P.B, P.T, brng)\n    PT = teacher.forward(X, W1s_t)[1][\"Pp\"]\n    W1s = prov.W_layers()\n    loss, cache = student.forward_distill(X, W1s, PT)\n    grads, Gs = student.backward(cache, W1s)\n    prov.backprop(Gs)\n    student.step(grads, 3e-3)\n    prov.step(3e-3)\n    kls.append(loss)\ncheck(\"smoke distill : la KL baisse\", kls[-1] < kls[0] * 0.9, f\"({kls[0]:.4f} → {kls[-1]:.4f})\")\ncheck(\"parent gauss : dist inter-couches non triviale\",\n      np.mean(par[\"field\"][\"diag\"][\"layer_dist\"]) > 0.05,\n      f\"(dist {np.mean(par['field']['diag']['layer_dist']):.1%})\")\n\nprint(\"\\nALL OK\" if ok else \"\\nÉCHEC\")\nsys.exit(0 if ok else 1)\n"